import sys; sys.path.insert(0,'/tmp/kit')
from elfkit import *
def probe(vals, bits=64, B=20):
    res={}
    off = 0x1000
    for i in range(0,len(vals),B):
        chunk=vals[i:i+B]
        h=run(build(bits=bits, shdrs=[dict(stype=1, off=off, size=0x10, flags=f) for f in chunk], filesize=0x2000))
        if h is None:
            print('ERR', run.err); continue
        for j,f in enumerate(chunk):
            d=dict(itable_rows(h,'info_shdr%d'%j) or [])
            res[f]=d.get('Flags:')
    return res
V=[0]+[1<<i for i in range(64)]+[0xffffffffffffffff]
r=probe(V)
for v in V:
    print('bit%-3s 0x%016x -> %r' % (('-' if v in (0,0xffffffffffffffff) else str(v.bit_length()-1)), v, r.get(v)))
